import { type NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { reviewService } from '@/features/reviews/services/review.service'
import { successResponse, errorResponse, unauthorizedResponse } from '@/utils/api'
import type {
  PortfolioAnalysis,
  GitHubAnalysis,
  ResumeAnalysis,
  AISummaryResult,
  AIMismatch,
} from '@/types'

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    let userId = user?.id

    const contentType = request.headers.get('content-type') || ''

    if (contentType.includes('application/json')) {
      const body = await request.json()
      const {
        portfolioUrl,
        githubUsername,
        resumeFileName,
        portfolio,
        github,
        resume,
        aiSummary,
        mismatches,
      } = body as {
        portfolioUrl?: string
        githubUsername?: string
        resumeFileName?: string
        portfolio?: PortfolioAnalysis | null
        github?: GitHubAnalysis | null
        resume?: ResumeAnalysis | null
        aiSummary?: AISummaryResult | null
        mismatches?: AIMismatch[]
      }

      if (!userId) {
        // Fallback mode: return success but don't save to DB so the frontend doesn't crash
        return successResponse({ id: 'fallback-no-save' }, 'Analysis complete (Guest Fallback Mode - Not Saved)')
      }

      const review = await reviewService.saveReviewWithResults(userId, {
        portfolioUrl,
        githubUsername,
        resumeFileName,
        portfolio,
        github,
        resume,
        aiSummary,
        mismatches,
      })

      return successResponse(review, 'Review saved successfully')
    }

    const formData = await request.formData()
    const portfolioUrl = formData.get('portfolioUrl') as string | null
    const githubUsername = formData.get('githubUsername') as string | null
    const resumeFile = formData.get('resume') as File | null

    let resumeBuffer: Buffer | undefined
    let resumeFileName: string | undefined

    if (resumeFile) {
      resumeBuffer = Buffer.from(await resumeFile.arrayBuffer())
      resumeFileName = resumeFile.name
    }

    if (!userId) {
      return errorResponse('Guest users cannot process files via form data endpoints. Please use the JSON endpoint.', 401)
    }

    const review = await reviewService.createFullReview(userId, {
      portfolioUrl: portfolioUrl || undefined,
      githubUsername: githubUsername || undefined,
      resumeBuffer,
      resumeFileName,
    })

    return successResponse(review, 'Review created successfully')
  } catch (error) {
    console.error('Save review API Error:', error)
    return errorResponse('Review creation failed', 500)
  }
}

export async function GET() {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user?.id) {
      return unauthorizedResponse('No active session found')
    }

    const reviews = await reviewService.getUserReviews(user.id)
    return successResponse(reviews, 'Reviews fetched successfully')
  } catch {
    return errorResponse('Failed to fetch reviews', 500)
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { urlValidationService } from '@/features/reviews/services/validation.service'

/**
 * POST /api/reviews/validate-portfolio
 * 
 * Layer 1 Validation Route.
 * Handles authentication and HTTP lifecycle, but delegates validation logic
 * to the ValidationService (Single Responsibility Principle).
 */
export async function POST(req: Request) {
  try {
    const supabase = await createClient()
    const { data: { session } } = await supabase.auth.getSession()
    // Validation is allowed for guests, so we don't return 401 if !session
    const { portfolioUrl } = await req.json()

    if (!portfolioUrl) {
      return NextResponse.json(
        { success: false, message: 'Portfolio URL is required' },
        { status: 400 }
      )
    }

    // Delegate business logic to the service
    const validationResult = await urlValidationService.validatePortfolioUrl(portfolioUrl);

    if (!validationResult.isValid) {
      return NextResponse.json({
        success: false,
        message: validationResult.message
      })
    }

    return NextResponse.json({
      success: true,
      data: { 
        valid: true, 
        isClientRendered: validationResult.isClientRendered 
      }
    })

  } catch (error: any) {
    return NextResponse.json(
      { success: false, message: 'An unexpected server error occurred during validation.' },
      { status: 500 }
    )
  }
}

'use client'

import { useState } from 'react'
import { Button } from '@/components/common/Button'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { Provider } from '@supabase/supabase-js'

interface ConnectProviderButtonProps {
  provider: Provider
  label: string
}

export function ConnectProviderButton({ provider, label }: ConnectProviderButtonProps) {
  const [isLoading, setIsLoading] = useState(false)
  const supabase = createClient()

  const handleConnect = async () => {
    setIsLoading(true)
    try {
      const { error } = await supabase.auth.linkIdentity({
        provider,
        options: {
          redirectTo: `${window.location.origin}/api/auth/callback?next=/account/accounts`
        }
      })
      if (error) throw error
      // The page will redirect to the provider's OAuth flow, so we don't necessarily need to reset isLoading
      // But if it fails to redirect, we'd want to reset it.
    } catch (error: any) {
      console.error(`Failed to connect ${provider}:`, error)
      toast.error(`Failed to connect ${provider}: ${error.message}`)
      setIsLoading(false)
    }
  }

  return (
    <Button 
      variant="outline" 
      className="rounded-xl font-bold shadow-sm shrink-0"
      onClick={handleConnect}
      disabled={isLoading}
    >
      {isLoading ? 'Connecting...' : label}
    </Button>
  )
}

'use client'

import { useState } from 'react'
import { Button } from '@/components/common/Button'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { UserIdentity } from '@supabase/supabase-js'
import { useRouter } from 'next/navigation'

interface DisconnectProviderButtonProps {
  identity: UserIdentity
  disabled: boolean
}

export function DisconnectProviderButton({ identity, disabled }: DisconnectProviderButtonProps) {
  const [isLoading, setIsLoading] = useState(false)
  const supabase = createClient()
  const router = useRouter()

  const handleDisconnect = async () => {
    if (disabled) {
      toast.error('You cannot disconnect your only login method.')
      return
    }

    setIsLoading(true)
    try {
      const { error } = await supabase.auth.unlinkIdentity(identity)
      if (error) throw error

      toast.success(`Successfully disconnected ${identity.provider}`)
      router.refresh()
    } catch (error: any) {
      console.error(`Failed to disconnect ${identity.provider}:`, error)
      toast.error(`Failed to disconnect ${identity.provider}: ${error.message}`)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Button 
      variant="ghost" 
      size="sm"
      className="text-red-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-500/10 ml-2 px-3 h-8"
      onClick={handleDisconnect}
      disabled={isLoading || disabled}
      title={disabled ? "Cannot disconnect your only login method" : `Disconnect ${identity.provider}`}
    >
      {isLoading ? 'Disconnecting...' : 'Disconnect'}
    </Button>
  )
}

'use client'

import { useState } from 'react'
import { Button } from '@/components/common/Button'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { Lock, Eye, EyeOff } from 'lucide-react'

export function UpdatePasswordForm() {
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [isUpdating, setIsUpdating] = useState(false)
  const supabase = createClient()

  const handleUpdate = async () => {
    if (!newPassword || newPassword.length < 6) {
      toast.error('Password must be at least 6 characters long')
      return
    }

    if (newPassword !== confirmPassword) {
      toast.error('Passwords do not match')
      return
    }

    setIsUpdating(true)
    try {
      const { error } = await supabase.auth.updateUser({
        password: newPassword
      })
      if (error) throw error

      toast.success('Password updated successfully!')
      setNewPassword('')
      setConfirmPassword('')
    } catch (error: any) {
      console.error('Failed to update password:', error)
      toast.error(error.message || 'Failed to update password')
    } finally {
      setIsUpdating(false)
    }
  }

  return (
    <div className="rounded-2xl border border-border/50 bg-card p-6 shadow-sm hover:shadow-md transition-shadow">
      <div className="flex items-center gap-2 mb-4">
        <Lock className="h-5 w-5 text-primary" />
        <h3 className="text-lg font-semibold text-foreground">Change Password</h3>
      </div>
      <p className="text-sm text-muted-foreground mb-6">
        Update the password you use to log in to your account.
      </p>

      <div className="grid gap-6 sm:grid-cols-2">
        <div className="space-y-2">
          <label className="text-sm font-medium text-muted-foreground">New Password</label>
          <div className="relative">
            <input 
              type={showPassword ? "text" : "password"} 
              value={newPassword} 
              onChange={(e) => setNewPassword(e.target.value)}
              className="w-full p-3 pr-10 bg-background rounded-xl border border-border/50 font-medium focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
              placeholder="Enter new password"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
            >
              {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
            </button>
          </div>
        </div>
        <div className="space-y-2">
          <label className="text-sm font-medium text-muted-foreground">Confirm New Password</label>
          <div className="relative">
            <input 
              type={showPassword ? "text" : "password"} 
              value={confirmPassword} 
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="w-full p-3 bg-background rounded-xl border border-border/50 font-medium focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
              placeholder="Confirm new password"
            />
          </div>
        </div>
      </div>
      <div className="mt-6 flex justify-end">
        <Button 
          variant="outline" 
          className="rounded-xl px-6 font-semibold shadow-sm border-primary/20 hover:bg-primary/5"
          onClick={handleUpdate}
          isLoading={isUpdating}
          disabled={!newPassword || !confirmPassword}
        >
          Update Password
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Button } from '@/components/common/Button'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import { Shield } from 'lucide-react'

interface UpdateProfileFormProps {
  initialName: string
  email: string
}

export function UpdateProfileForm({ initialName, email }: UpdateProfileFormProps) {
  const [name, setName] = useState(initialName)
  const [isUpdating, setIsUpdating] = useState(false)
  const supabase = createClient()
  const router = useRouter()

  const handleUpdate = async () => {
    if (!name.trim()) {
      toast.error('Name cannot be empty')
      return
    }

    if (name === initialName) {
      toast.info('No changes to save')
      return
    }

    setIsUpdating(true)
    try {
      const { error } = await supabase.auth.updateUser({
        data: { full_name: name.trim() }
      })
      if (error) throw error

      toast.success('Profile updated successfully!')
      router.refresh()
    } catch (error: any) {
      console.error('Failed to update profile:', error)
      toast.error(error.message || 'Failed to update profile')
    } finally {
      setIsUpdating(false)
    }
  }

  return (
    <div className="rounded-2xl border border-border/50 bg-card p-6 shadow-sm hover:shadow-md transition-shadow">
      <div className="grid gap-6 sm:grid-cols-2">
        <div className="space-y-2">
          <label className="text-sm font-medium text-muted-foreground">Full Name</label>
          <input 
            type="text" 
            value={name} 
            onChange={(e) => setName(e.target.value)}
            className="w-full p-3 bg-muted/30 rounded-xl border border-border/50 font-medium focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
            placeholder="Enter your full name"
          />
        </div>
        <div className="space-y-2">
          <label className="text-sm font-medium text-muted-foreground">Email Address</label>
          <div className="p-3 bg-muted/30 rounded-xl border border-border/50 font-medium flex items-center justify-between opacity-80 cursor-not-allowed" title="Email address cannot be changed here">
            {email}
            <Shield className="h-4 w-4 text-green-500" />
          </div>
        </div>
      </div>
      <div className="mt-6 flex justify-end">
        <Button 
          variant="default" 
          className="rounded-xl px-6 font-semibold shadow-sm"
          onClick={handleUpdate}
          isLoading={isUpdating}
          disabled={name === initialName}
        >
          Update Profile
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import Link from 'next/link'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { loginSchema, registerSchema, type LoginInput, type RegisterInput } from '@/validations/auth'
import { authService } from '@/features/auth/services/auth.service'
import { ROUTES } from '@/constants'
import { Button } from '@/components/common/Button'
import { Input } from '@/components/common/Input'
import { AlertCircle, Eye, EyeOff, ArrowLeft, CheckCircle2 } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { TermsModal } from '@/components/legal/TermsModal'
import { PrivacyModal } from '@/components/legal/PrivacyModal'

interface AuthScreenProps {
  initialMode: 'login' | 'register'
  isModal?: boolean
  onSuccess?: () => void
  onClose?: () => void
}

export function AuthScreen({ initialMode, isModal, onSuccess, onClose }: AuthScreenProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const nextPath = searchParams?.get('next') || undefined
  
  const [isLogin, setIsLogin] = useState(initialMode === 'login')
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  
  // Login State
  const [loginError, setLoginError] = useState<string | null>(null)
  const [isLoginLoading, setIsLoginLoading] = useState(false)
  
  // Register State
  const [registerError, setRegisterError] = useState<string | null>(null)
  const [isRegisterLoading, setIsRegisterLoading] = useState(false)
  const [registerSuccess, setRegisterSuccess] = useState(false)

  // Modals
  const [showTermsModal, setShowTermsModal] = useState(false)
  const [showPrivacyModal, setShowPrivacyModal] = useState(false)

  // Sync state if user uses browser back/forward buttons
  useEffect(() => {
    setIsLogin(pathname === '/login')
  }, [pathname])

  const handleSwitchMode = () => {
    const newMode = !isLogin
    setIsLogin(newMode)
    if (!isModal) {
      const newUrl = (newMode ? ROUTES.login : ROUTES.register) + (nextPath ? `?next=${nextPath}` : '')
      window.history.pushState(null, '', newUrl)
    }
  }

  // --- Forms Setup ---
  const loginForm = useForm<LoginInput>({
    resolver: zodResolver(loginSchema),
  })

  const registerForm = useForm<RegisterInput>({
    resolver: zodResolver(registerSchema),
  })

  // --- Submit Handlers ---
  const onLoginSubmit = async (data: LoginInput) => {
    setIsLoginLoading(true)
    setLoginError(null)
    try {
      const result = await authService.signIn(data.email, data.password)
      try { await fetch('/api/auth/merge', { method: 'POST' }) } catch (e) {}
      toast.success('Signed in successfully')
      
      const hasUsername = !!result.user?.user_metadata?.username
      
      if (!hasUsername) {
        router.push('/onboarding')
        router.refresh()
      } else if (onSuccess) {
        onSuccess()
        window.location.reload()
      } else {
        router.push(nextPath || ROUTES.dashboard)
        router.refresh()
      }
    } catch (err: unknown) {
      const errorMsg = err instanceof Error ? err.message : 'Invalid email or password'
      toast.error(errorMsg)
      setLoginError(errorMsg)
    } finally {
      setIsLoginLoading(false)
    }
  }

  const onRegisterSubmit = async (data: RegisterInput) => {
    setIsRegisterLoading(true)
    setRegisterError(null)
    try {
      const result = await authService.signUp(data.email, data.password, data.fullName)
      
      // If session exists, email confirmation is disabled and they are logged in immediately
      if (result && 'session' in result && result.session) {
        try { await fetch('/api/auth/merge', { method: 'POST' }) } catch (e) {}
        toast.success('Account created successfully')
        
        const hasUsername = !!result.user?.user_metadata?.username
        
        if (!hasUsername) {
          router.push('/onboarding')
          router.refresh()
        } else if (onSuccess) {
          onSuccess()
          window.location.reload()
        } else {
          router.push(nextPath || ROUTES.dashboard)
          router.refresh()
        }
      } else {
        toast.success('Account created! Check your email to confirm.')
        setRegisterSuccess(true)
      }
    } catch (err: unknown) {
      const errorMsg = err instanceof Error ? err.message : 'Something went wrong.'
      toast.error(errorMsg)
      setRegisterError(errorMsg)
    } finally {
      setIsRegisterLoading(false)
    }
  }

  const handleGoogleSignIn = async () => {
    try {
      await authService.signInWithGoogle(nextPath)
    } catch (err) {
      toast.error('Failed to initialize Google sign in')
    }
  }

  const handleGithubSignIn = async () => {
    try {
      await authService.signInWithGithub(nextPath)
    } catch (err) {
      toast.error('Failed to initialize GitHub sign in')
    }
  }

  if (registerSuccess) {
    return (
      <div className={cn("flex items-center justify-center px-4", isModal ? "min-h-full bg-transparent" : "min-h-screen bg-slate-50 dark:bg-slate-950")}>
        {!isModal && (
          <Link href="/" className="absolute left-4 top-4 md:left-8 md:top-8 flex items-center text-sm font-medium text-muted-foreground hover:text-foreground transition-colors">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Home
          </Link>
        )}
        <div className="w-full max-w-sm text-center space-y-6">
          <div className="flex justify-center">
            <div className="rounded-full bg-emerald-500/10 p-3">
              <CheckCircle2 className="h-8 w-8 text-emerald-500" />
            </div>
          </div>
          <div className="space-y-2">
            <h1 className="text-2xl font-bold">Check your email</h1>
            <p className="text-muted-foreground">
              We've sent a confirmation link to your email. Click the link to activate your account.
            </p>
          </div>
          <button onClick={() => { setRegisterSuccess(false); setIsLogin(true); window.history.pushState(null, '', ROUTES.login) }} className="inline-block text-sm text-primary hover:underline font-medium">
            Back to login
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className={cn("relative w-full overflow-hidden flex items-center justify-center text-foreground", isModal ? "min-h-full bg-transparent" : "min-h-screen bg-background")}>
      
      {/* Premium Background Engine */}
      <div className={cn("absolute inset-0 -z-10 overflow-hidden", isModal ? "bg-transparent rounded-[2.5rem]" : "bg-slate-50 dark:bg-[#0B0F19]")}>
         {/* SVG Grid Lines */}
         <div className="absolute inset-0 bg-[linear-gradient(to_right,#8080801a_1px,transparent_1px),linear-gradient(to_bottom,#8080801a_1px,transparent_1px)] bg-[size:40px_40px] [mask-image:radial-gradient(ellipse_80%_80%_at_50%_50%,#000_20%,transparent_100%)]"></div>
         
         <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] opacity-70 mix-blend-multiply dark:mix-blend-screen pointer-events-none transition-transform duration-1000 ease-in-out">
            <div className={cn(
              "absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(59,130,246,0.35)_0%,transparent_50%)] blur-[80px] transition-all duration-1000",
              isLogin ? "translate-x-1/4 scale-110" : "-translate-x-1/4 scale-90"
            )} />
            <div className={cn(
              "absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(168,85,247,0.35)_0%,transparent_50%)] blur-[80px] transition-all duration-1000 delay-100",
              isLogin ? "-translate-x-1/4 translate-y-1/4 scale-90" : "translate-x-1/4 -translate-y-1/4 scale-110"
            )} />
         </div>
      </div>

      {!isModal && (
        <Link href="/" className="absolute left-6 top-6 z-50 flex items-center text-sm font-medium text-foreground/60 hover:text-foreground transition-colors bg-background/20 backdrop-blur-md px-4 py-2 rounded-full border border-border/50 hover:bg-background/40">
          <ArrowLeft className="mr-2 h-4 w-4" />
          Home
        </Link>
      )}

      {isModal && onClose && (
        <button onClick={onClose} className="absolute right-6 top-6 z-50 text-foreground/60 hover:text-foreground bg-background/20 backdrop-blur-md p-2 rounded-full border border-border/50 hover:bg-background/40 transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
        </button>
      )}

      {/* Main Container */}
      <div className={cn("relative w-full max-w-[1200px] h-[750px] max-h-[90vh] bg-background/60 dark:bg-slate-900/40 backdrop-blur-2xl rounded-3xl border border-border/50 overflow-hidden flex flex-col md:flex-row mx-4", isModal ? "shadow-none" : "shadow-[0_0_80px_-20px_rgba(0,0,0,0.1)] dark:shadow-[0_0_80px_-20px_rgba(0,0,0,0.5)]")}>
        
        {/* SLIDING OVERLAY PANEL */}
        <div className={cn(
          "hidden md:flex absolute top-0 w-1/2 h-full bg-gradient-to-br from-blue-600 to-purple-600 z-20 items-center justify-center flex-col text-white transition-transform duration-[800ms] ease-[cubic-bezier(0.16,1,0.3,1)] shadow-2xl",
          isLogin ? "translate-x-full rounded-l-[40px]" : "translate-x-0 rounded-r-[40px]"
        )}>
          {/* Overlay Content: Register (Shows when on Login side) */}
          <div className={cn(
            "absolute inset-0 flex flex-col items-center justify-center p-16 text-center transition-all duration-700 delay-100",
            isLogin ? "opacity-100 translate-x-0 pointer-events-auto" : "opacity-0 -translate-x-20 pointer-events-none"
          )}>
            <div className="relative w-64 h-64 mb-8">
              {/* Subtle pulsing glow behind the image */}
              <div className="absolute inset-0 bg-white/20 blur-3xl rounded-full mix-blend-overlay animate-pulse" />
              <img 
                src="/auth-hero.png" 
                alt="PortfolioPilot Dashboard Graphic" 
                className="relative z-10 w-full h-full object-contain animate-float"
              />
            </div>
            <h2 className="text-4xl font-extrabold mb-4 tracking-tight drop-shadow-sm">New Here?</h2>
            <p className="text-lg text-white/80 mb-10 leading-relaxed font-medium">
              Join thousands of candidates optimizing their portfolios with our AI orchestrator.
            </p>
            <Button onClick={handleSwitchMode} variant="outline" size="lg" className="rounded-full px-12 border-2 border-white/40 text-white bg-transparent hover:bg-white hover:text-blue-600 font-bold transition-all duration-300">
              Create Account
            </Button>
          </div>

          {/* Overlay Content: Login (Shows when on Register side) */}
          <div className={cn(
            "absolute inset-0 flex flex-col items-center justify-center p-16 text-center transition-all duration-700 delay-100",
            !isLogin ? "opacity-100 translate-x-0 pointer-events-auto" : "opacity-0 translate-x-20 pointer-events-none"
          )}>
            <div className="relative w-64 h-64 mb-8">
              {/* Subtle pulsing glow behind the image */}
